	var q int32 = 0
	var c int32 = 0
	var ts int32 = 0
	var tl int32 = 0
	var src int32 = 0
	var hidden int32 = 0
	var minscore int32 = 1000
	var any int32 = 0
	var cover int32 = 0
	var ask int32 = 0
	var at int32 = 0
	var made int32 = 0
	var total int32 = 0
	var ix0 int32 = 0
	var iy0 int32 = 0
	var ix1 int32 = 0
	var iy1 int32 = 0
